// CampusPilot static demo. All personal records are fictional. No external calls or LLM inference occur.
// This script is a real, deterministic offline interaction layer, not a production access-control implementation.
const baseCourses=[
 {id:'NS',name:'Network Security',code:'CS201',attended:21,total:27,upcoming:4,miss:{full:2,partial:1,skip:0}},
 {id:'DB',name:'Database Systems',code:'CS203',attended:25,total:32,upcoming:3,miss:{full:1,partial:0,skip:0}},
 {id:'DM',name:'Discrete Mathematics',code:'MA202',attended:29,total:36,upcoming:2,miss:{full:0,partial:0,skip:0}},
];
const options=[
 {id:'full',title:'Attend full event',badge:'MAXIMUM PARTICIPATION',description:'Two days on site. Academic conflicts require additional review.',summary:'Example attendance shortfall',status:'warn'},
 {id:'partial',title:'Attend selected sessions',badge:'PREFERRED FOR REVIEW',description:'Prioritize non-overlapping sessions and retain more class attendance.',summary:'Numerically feasible; approval pending',status:'good'},
 {id:'skip',title:'Defer participation',badge:'ACADEMIC-FIRST',description:'Protect study time and evaluate a later cybersecurity event.',summary:'No event-related absence',status:'neutral'},
];
const defaultState={chosen:'partial',deadlineEarlier:false,approved:false,lastChange:false};
function load(){try{let s=JSON.parse(localStorage.getItem('campuspilot_static_v2')||'{}');return {...defaultState,...s}}catch{return {...defaultState}}}
let state=load();const el=id=>document.getElementById(id);const pct=(a,b)=>(100*a/b);const fmt=v=>Number(v).toFixed(1)+'%';const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){try{localStorage.setItem('campuspilot_static_v2',JSON.stringify(state))}catch{/* storage unavailable: in-memory demo still works */}}
function toast(message){const node=el('toast');node.textContent=message;node.classList.add('show');window.clearTimeout(toast.timer);toast.timer=window.setTimeout(()=>node.classList.remove('show'),3100)}
function view(name){for(const node of document.querySelectorAll('.view'))node.classList.toggle('is-visible',node.id==='view-'+name);for(const node of document.querySelectorAll('.nav-item'))node.classList.toggle('active',node.dataset.view===name);el('currentCrumb').textContent=({overview:'Overview',planner:'Decision studio',activity:'Agent activity',security:'Trust center'})[name];window.scrollTo({top:0,behavior:'smooth'});}
function impact(course,opt){let miss=course.miss[opt];return{pct:pct(course.attended+course.upcoming-miss,course.total+course.upcoming),before:pct(course.attended,course.total),attended:course.attended+course.upcoming-miss,total:course.total+course.upcoming,miss}}
function attendance(){el('attendanceSnapshot').innerHTML=baseCourses.map(c=>{const cur=pct(c.attended,c.total);return `<div class="course-row"><div class="course-icon">${c.id}</div><div class="course-main"><div class="course-line"><strong>${escapeHtml(c.name)}</strong><span class="percent">${fmt(cur)}</span></div><div class="course-description">${c.attended} of ${c.total} classes attended · ${c.code}</div><div class="progress"><div class="${cur<79?'weak':''}" style="width:${cur}%"></div></div></div></div>`}).join('')}
function renderOptions(){el('options').innerHTML=options.map(o=>`<button class="option ${state.chosen===o.id?'active':''}" data-option="${o.id}" aria-pressed="${state.chosen===o.id}"><div class="option-top"><span class="option-badge">${o.badge}</span><span class="radio">${state.chosen===o.id?'✓':''}</span></div><h4>${o.title}</h4><p>${o.description}</p><div class="option-outcome ${o.status}">${o.status==='warn'?'⚠':o.status==='good'?'✓':'◷'} ${o.summary}</div></button>`).join('');document.querySelectorAll('[data-option]').forEach(btn=>btn.addEventListener('click',()=>{state.chosen=btn.dataset.option;state.approved=false;save();render();toast('Alternative recalculated using the example attendance policy.')}))}
function renderProjection(){const threshold=75;el('attendanceProjection').innerHTML=baseCourses.map(c=>{const after=impact(c,state.chosen);const ok=after.pct>=threshold;return `<div class="projected-course"><div class="projected-name"><strong>${escapeHtml(c.name)}</strong><span class="projected-number ${ok?'ok':'bad'}">${fmt(after.pct)} ${ok?'✓':'⚠'}</span></div><div class="progress"><div class="${ok?'':'weak'}" style="width:${after.pct}%"></div></div><div class="course-description">${after.attended}/${after.total} projected · ${after.miss} event-related absences · example threshold 75%</div></div>`}).join('')}
function tasks(){const core=[];if(state.chosen==='full')core.push({name:'Reconsider full-event attendance',desc:'Network Security projection is 74.2%, below the illustrative threshold. Do not treat this plan as approved.'});if(state.chosen==='partial')core.push({name:'Confirm selected-session participation',desc:'Check actual session timing, eligibility, and advance on-duty approval with the appropriate authority.'});if(state.chosen==='skip')core.push({name:'Find a later opportunity',desc:'Keep academic commitments and review alternative event dates.'});if(state.deadlineEarlier)core.push({name:'Reschedule database project work',desc:'Deadline moved to Oct 28, 7 PM. Move the planned project work to Oct 27 and seek confirmation.'});else core.push({name:'Finish database mini-project early',desc:'Prepare submission before the Oct 29, 6 PM example deadline; submission itself is not automated.'});core.push({name:'Reserve internal-assessment preparation',desc:'Protect a three-hour preparation block before the Oct 31, 9 AM assessment.'});return core}
function renderPlan(){el('planActions').innerHTML=tasks().map((s,i)=>`<div class="plan-step"><div class="step-dot">${i+1}</div><div><strong>${escapeHtml(s.name)}</strong><p>${escapeHtml(s.desc)}</p></div></div>`).join('');el('planStatus').textContent=state.approved?'Saved locally':'Awaiting approval';el('approvePlan').textContent=state.approved?'✓ Plan saved — change and reapprove':'Approve my action plan →';el('savedMessage').classList.toggle('hidden',!state.approved);el('approvePlan').disabled=state.approved;el('approvePlan').style.opacity=state.approved?'.67':'1'}
function renderDeadline(){el('scenarioDeadlineText').textContent=state.deadlineEarlier?'Updated due date: Oct 28, 7:00 PM':'Current due date: Oct 29, 6:00 PM';el('overviewDeadline').textContent=state.deadlineEarlier?'Project deadline advanced to Oct 28 at 7:00 PM.':'Project currently due Oct 29 at 6:00 PM.';el('timelineAssignmentDate').innerHTML=state.deadlineEarlier?'28<small>OCT</small>':'29<small>OCT</small>';el('timelineDeadline').textContent=state.deadlineEarlier?'Updated assignment · Oct 28, 7:00 PM':'Assignment · 6:00 PM';el('simulateChange').textContent=state.deadlineEarlier?'↻ Restore original deadline':'Move deadline earlier →';el('replanningNotice').classList.toggle('hidden',!state.deadlineEarlier);el('replanningNotice').innerHTML='✳ <strong>Replanning triggered by a source-record change.</strong><br>The assignment is now due on Oct 28 at 7 PM instead of Oct 29 at 6 PM. Your current plan needs reapproval. Move planned project work to Oct 27, then check that your assessment preparation still fits. <strong>This is a deterministic local event watcher, not a live ERP sync or LLM run.</strong>'}
function renderActivity(){const ns=impact(baseCourses[0],state.chosen),db=impact(baseCourses[1],state.chosen);const steps=[['01','Personal orchestrator','Reads the fictional student objective and selects the feasibility workflow.','read(student_goal), dispatch(academic,opportunity)','⌘'],['02','Academic specialist','Retrieves attendance counts, three coursework commitments and the sample attendance-policy setting.','read(academic_records), read(sample_policy)','▤'],['03','Opportunity specialist','Checks example CyberForge dates, session choices, and submission conditions.','read(example_event), identify(time_conflicts)','✦'],['04','Constraint evaluator',`Computes Network Security ${fmt(ns.pct)} and Database Systems ${fmt(db.pct)} for the selected alternative. These numbers are generated in JavaScript, not written by an LLM.`, 'compute_projected_attendance(), compare_example_threshold()','◷'],['05','Planning workflow',`Reconciles the selected option with ${state.deadlineEarlier?'the moved Oct 28':'the original Oct 29'} database deadline and Oct 31 assessment.`, 'create_plan(candidate_actions), require_approval()','▦'],['06','Permission checkpoint',`Plan is ${state.approved?'approved and saved in localStorage':'waiting for student approval'}. This prototype never writes to an actual ERP.`, 'authorize(demo_local_task_write), verify(local_storage)','◇']];el('activityList').innerHTML=steps.map(s=>`<div class="activity-step"><div class="agent-symbol">${s[4]}</div><div><div class="eyebrow">STEP ${s[0]} · ILLUSTRATIVE WORKFLOW</div><h4>${s[1]}</h4><p>${s[2]}</p><code>${s[3]}</code></div><span class="step-state">DEMO STEP</span></div>`).join('')}
function render(){attendance();renderOptions();renderProjection();renderPlan();renderDeadline();renderActivity()}
function modal(heading,eyebrow,content){el('modalHeading').textContent=heading;el('modalEyebrow').textContent=eyebrow;el('modalContent').innerHTML=content;el('modalBackdrop').classList.remove('hidden')}
function closeModal(){el('modalBackdrop').classList.add('hidden')}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.go)));
el('recalculate').addEventListener('click',()=>{render();toast('Recomputed from current local academic records.');});
el('resetScenario').addEventListener('click',()=>{state={...defaultState};save();render();toast('Example data restored.');});
el('approvePlan').addEventListener('click',()=>{state.approved=true;save();render();toast('Approved plan persisted in this browser (demo only).')});
el('simulateChange').addEventListener('click',()=>{state.deadlineEarlier=!state.deadlineEarlier;state.approved=false;save();render();toast(state.deadlineEarlier?'Source change detected → plan revised.':'Original deadline restored → plan revised.')});
el('trySecurity').addEventListener('click',()=>{el('securityResult').classList.remove('hidden');toast('Demo-only cross-profile read denied.');});
el('attendanceWhy').addEventListener('click',()=>modal('Projecting attendance','EXPLAINABLE MATH',`<p>For a hypothetical course with <strong>A</strong> attended sessions and <strong>T</strong> total sessions, when <strong>H</strong> more sessions are scheduled and the student would miss <strong>M</strong> of them because of the event:</p><pre>Projected attendance = (A + H − M) / (T + H) × 100</pre><p>Example for full participation in Network Security: <strong>(21 + 4 − 2) / (27 + 4) = 23/31 = 74.2%</strong>.</p><p>Partial participation: <strong>(21 + 4 − 1)/31 = 24/31 = 77.4%</strong>.</p><p class="small-note">Assumes the student attends every other future scheduled session. The 75% cutoff is configured for this example and does not establish personal exam eligibility. OD, regulations, course-specific rules, academic calendar changes and exceptions must be separately verified.</p>`));
el('openSources').addEventListener('click',()=>modal('Connected sources','TRANSPARENCY',`<p><strong>Academic simulator:</strong> fictional courses, attendance, assignments, assessments and example rules stored inside this prototype.</p><p><strong>Opportunity example:</strong> CyberForge Sprint is an invented demonstration opportunity, not a real verified hackathon listing.</p><p><strong>Student profile:</strong> Maya Rao is fictional.</p><p><strong>VTOP:</strong> no connection. No university login, password or private records are used.</p><p><strong>LLM:</strong> no live API requests. This static preview demonstrates UI, deterministic calculation, local persistence and state transitions only.</p>`));
el('notifications').addEventListener('click',()=>toast('No live notifications are enabled in the static demo.'));
el('pitchMode').addEventListener('click',()=>{document.body.classList.toggle('pitch-mode');toast(document.body.classList.contains('pitch-mode')?'Presentation mode on (press P to exit).':'Presentation mode off.');});
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='p'&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!(e.target instanceof HTMLInputElement))document.body.classList.toggle('pitch-mode')});
el('closeModal').addEventListener('click',closeModal);el('modalOkay').addEventListener('click',closeModal);el('modalBackdrop').addEventListener('click',e=>{if(e.target===el('modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
